import { SITE_NAME } from '@/lib/brand';

// Generated by scripts/make-logo.cjs (608×204, transparent background)
const SRC = {
  dark: '/brand/meskan-logo.png', // navy logo, for light backgrounds
  light: '/brand/meskan-logo-white.png', // white logo, for dark backgrounds
};

/**
 * Meskan dz logo. Set the size with a height class (e.g. "h-10"); width follows the
 * aspect ratio. Width/height attributes reserve the space so nothing shifts on load.
 */
export default function BrandLogo({ variant = 'dark', className = 'h-10', alt = SITE_NAME, priority = false }) {
  return (
    <img
      src={SRC[variant]}
      alt={alt}
      width={608}
      height={204}
      className={`${className} w-auto select-none`}
      draggable={false}
      fetchPriority={priority ? 'high' : undefined}
    />
  );
}
